   159:    // Similar to using the bin directory in HOME on Unix, we only install for the current user
   160:    // on Windows.
   161:    let company = CURRENT_USER.create(format!("Software\\Python\\{COMPANY_KEY}"))?;
   162:    company.set_string("DisplayName", COMPANY_DISPLAY_NAME)?;
   163:    company.set_string("SupportUrl", "https://github.com/astral-sh/uv")?;
   164:
