   169:        installation.key().implementation().pretty(),
   170:        installation.key().version(),
   171:        pointer_width
   172:    );
   173:    tag.set_string("DisplayName", &display_name)?;
   174:    tag.set_string("SupportUrl", "https://github.com/astral-sh/uv")?;
   175:    tag.set_string("Version", installation.key().version().to_string())?;
   176:    tag.set_string("SysVersion", installation.key().sys_version())?;
   177:    tag.set_string("SysArchitecture", format!("{pointer_width}bit"))?;
